 41: export default function NewChatScreen() {
 42:   const theme = useTheme();
 43:   const c = theme.colors;
 44:   const router = useRouter();
 45:   const net = useNetState();
 46:   const { session } = useAuth();
 47:   const { showToast } = useToast();
 48:   const userId = session?.user.id ?? null;
 49: 
 50:   const [username, setUsername] = useState('');
 51:   const [search, setSearch] = useState<SearchState>({ status: 'idle' });
 52:   const [opening, setOpening] = useState(false);
 53: 
 54:   const trimmed = dgTrim(username);
 55:   const searching = search.status === 'searching';
 56:   const canFind = net.isConnected && trimmed.length > 0 && !searching && !opening;
