 58:   const onFind = useCallback(async () => {
 59:     if (!canFind) return;
 60:     setSearch({ status: 'searching' });
 61:     const { data, error } = await findUser(supabase, trimmed);
 62:     if (error) {
 63:       setSearch({ status: 'error', message: searchErrorMessage(error) });
 64:       return;
 65:     }
 66:     const found = data[0] ?? null;
 67:     setSearch(found === null ? { status: 'notFound' } : { status: 'found', user: found });
 68:   }, [canFind, trimmed]);
