 70:   const onMessage = useCallback(
 71:     async (user: FindUserRow) => {
 72:       if (!userId || opening) return;
 73:       setOpening(true);
 74:       try {
 75:         const db = await getLocalDatabase();
 76:         const outcome = await openDirectChat({
 77:           client: supabase,
 78:           db,
 79:           userId,
 80:           otherUserId: user.user_id,
 81:           newChatId: ids.chatId(),
 82:         });
 83:         if (outcome.kind === 'failed') {
 84:           showToast({ message: outcome.message });
 85:           return;
 86:         }
 87:         router.replace({ pathname: '/chat/[chatId]', params: { chatId: outcome.chatId } });
 88:       } catch {
 89:         showToast({ message: strings.newChat.openFailed });
 90:       } finally {
 91:         setOpening(false);
 92:       }
 93:     },
 94:     [userId, opening, router, showToast],
 95:   );
 96: 
 97:   return (
 98:     <View style={[styles.screen, { backgroundColor: c.bg.app }]}>
