100: 
101:       <ScrollView
102:         contentContainerStyle={[styles.body, { padding: theme.space[4], gap: theme.space[4] }]}
103:         keyboardShouldPersistTaps="handled"
104:       >
105:         <TextField
106:           label={strings.newChat.usernameLabel}
107:           helper={strings.newChat.usernameHelper}
108:           value={username}
109:           onChangeText={(next) => {
110:             setUsername(next);
111:             setSearch({ status: 'idle' });
112:           }}
113:           onSubmitEditing={() => void onFind()}
114:           autoCapitalize="none"
