122:           onPress={() => void onFind()}
123:           disabled={!canFind}
124:           loading={searching}
125:         />
126: 
127:         {net.isConnected ? null : (
128:           <Text style={[textStyle(theme.typeTokens.bodySm), { color: c.text.secondary }]}>
129:             {strings.common.noConnection}
