131:         )}
132: 
133:         {search.status === 'notFound' ? (
134:           <Text style={[textStyle(theme.typeTokens.bodyMd), { color: c.text.secondary }]}>
135:             {strings.newChat.notFound}
136:           </Text>
137:         ) : null}
138: 
139:         {search.status === 'error' ? (
