 29: function AccountSearch({ userId }: { userId: string }) {
 30:   const theme = useTheme();
 31:   const router = useRouter();
 32:   const { originX } = useLocalSearchParams<{ originX?: string }>();
 33:   const insets = useSafeAreaInsets();
 34:   const { width } = useWindowDimensions();
 35:   const origin = Number(originX);
 36:   const canExpand = Number.isFinite(origin) && !theme.reduceMotion;
 37:   const progress = useRef(new Animated.Value(canExpand ? 0 : 1)).current;
 38:   const input = useRef<TextInput>(null);
 39:   const opening = useRef(false);
 40:   const [query, setQuery] = useState('');
 41:   const normalized = normalizeSearch(query);
 42:   const { active, archived, ignored, loading, error, reload } = useChatList();
 43:   const chats = useMemo(() => [...active, ...archived, ...ignored], [active, archived, ignored]);
 44:   const chatIds = useMemo(() => JSON.stringify(chats.map((chat) => chat.chatId).sort()), [chats]);
 45:   const duration = theme.duration('normal');
 46:   const startLeft = Math.max(0, Math.min(width - SEARCH_BUTTON_WIDTH, origin - SEARCH_BUTTON_WIDTH / 2));
 47: 
 48:   useFocusEffect(useCallback(() => { opening.current = false; }, []));
 49:   useEffect(() => {
 50:     if (!canExpand) {
 51:       progress.setValue(1);
 52:       input.current?.focus();
 53:       return;
 54:     }
 55:     const transition = Animated.timing(progress, {
 56:       toValue: 1, duration, easing: Easing.out(Easing.cubic), useNativeDriver: false,
 57:     });
 58:     transition.start(({ finished }) => { if (finished) input.current?.focus(); });
 59:     return () => transition.stop();
 60:   }, [canExpand, duration, progress]);
 61: 
 62:   const openChat = useCallback((chatId: string, focusMessageId?: string) => {
 63:     if (opening.current) return;
 64:     opening.current = true;
 65:     Keyboard.dismiss();
 66:     router.push({
 67:       pathname: '/chat/[chatId]',
 68:       params: focusMessageId ? { chatId, focusMessageId } : { chatId },
 69:     });
 70:   }, [router]);
 71: 
 72:   return (
 73:     <View style={styles.screen} accessibilityViewIsModal>
 74:       <Animated.View
 75:         pointerEvents="none"
 76:         style={[StyleSheet.absoluteFill, { backgroundColor: theme.colors.bg.app, opacity: progress }]}
 77:       />
 78:       <View style={[styles.toolbar, { marginTop: insets.top }]}>
 79:         <Animated.View style={{ marginLeft: insets.left + 4, opacity: progress }}>
 80:           <IconButton iconName="nav.back" accessibilityLabel="Go back" onPress={() => goBackOrReplace(router)} />
 81:         </Animated.View>
 82:         <Animated.View style={[
 83:           styles.field,
 84:           {
 85:             left: canExpand ? progress.interpolate({ inputRange: [0, 1], outputRange: [startLeft, insets.left + 52] }) : insets.left + 52,
 86:             right: canExpand ? progress.interpolate({ inputRange: [0, 1], outputRange: [width - startLeft - SEARCH_BUTTON_WIDTH, insets.right + 12] }) : insets.right + 12,
 87:           },
 88:         ]}>
 89:           <SearchField
 90:             inputRef={input}
 91:             placeholder="Search chats and messages"
 92:             accessibilityLabel="Search chats and messages"
 93:             autoCapitalize="none"
 94:             autoCorrect={false}
 95:             onSearch={setQuery}
 96:             debounceMs={0}
 97:           />
 98:         </Animated.View>
 99:       </View>
100:       <Animated.View style={[styles.screen, { opacity: progress, paddingBottom: insets.bottom }]}>
101:         {!normalized ? (
102:           <EmptyState iconName="action.search" title="Search DoloGram" message="Find conversations, messages and attachments." />
103:         ) : error && chats.length === 0 ? (
104:           <ErrorState title="Couldn't load chats" message="Try searching again." onRetry={() => void reload()} />
105:         ) : loading ? (
106:           <ActivityIndicator style={styles.loader} color={theme.colors.brand.primary} accessibilityLabel="Loading chats" />
107:         ) : (
108:           <SearchResults key={JSON.stringify([normalized, chatIds])} chats={chats} chatIds={chatIds} userId={userId} query={normalized} openChat={openChat} />
109:         )}
110:       </Animated.View>
111:     </View>
112:   );
113: }
