115: type Result = { chat: ChatListItem } | { message: MessageMatch };
116: 
117: function SearchResults({ chats, chatIds, userId, query, openChat }: {
118:   chats: ChatListItem[];
119:   chatIds: string;
120:   userId: string;
121:   query: string;
122:   openChat: (chatId: string, messageId?: string) => void;
123: }) {
124:   const theme = useTheme();
125:   const chatsById = useMemo(() => new Map(chats.map((chat) => [chat.chatId, chat])), [chats]);
126:   const [results, setResults] = useState<MessageMatch[]>([]);
127:   const [next, setNext] = useState<SearchCursor | null>(null);
128:   const [request, setRequest] = useState<{ cursor: SearchCursor | null }>({ cursor: null });
129:   const [settled, setSettled] = useState<typeof request | null>(null);
130:   const [failed, setFailed] = useState(false);
131:   const loading = settled !== request;
132: 
133:   useEffect(() => subscribeCacheChange(() => setRequest({ cursor: null })), []);
134:   useEffect(() => {
135:     const controller = new AbortController();
136:     const search = async () => {
137:       try {
138:         const page = chatIds === '[]' ? { matches: [], next: null } : await searchCachedMessages(
139:           await getLocalDatabase(), userId, chatIds, query, request.cursor, controller.signal,
140:         );
141:         if (controller.signal.aborted) return;
142:         setResults((previous) => request.cursor ? [...previous, ...page.matches] : page.matches);
143:         setNext(page.next);
144:         setFailed(false);
145:       } catch {
146:         if (!controller.signal.aborted) setFailed(true);
147:       } finally {
148:         if (!controller.signal.aborted) setSettled(request);
149:       }
150:     };
151:     const timer = setTimeout(() => void search(), request.cursor ? 0 : 150);
152:     return () => { clearTimeout(timer); controller.abort(); };
153:   }, [chatIds, query, request, userId]);
154: 
155:   const matchingChats = chats.filter((chat) => normalizeSearch(chat.title).includes(query));
156:   const messages = results.filter((message) => chatsById.has(message.chatId));
157:   const sections: { title: string; data: Result[] }[] = [
158:     { title: 'Chats', data: matchingChats.map((chat) => ({ chat })) },
159:     { title: 'Messages', data: messages.map((message) => ({ message })) },
160:   ].filter((section) => section.data.length > 0);
161: 
162:   return (
163:     <SectionList<Result>
164:       sections={sections}
165:       keyboardShouldPersistTaps="handled"
166:       keyboardDismissMode="on-drag"
167:       stickySectionHeadersEnabled={false}
168:       keyExtractor={(item) => 'chat' in item ? `chat:${item.chat.chatId}` : item.message.messageId}
169:       renderSectionHeader={({ section }) => (
170:         <Text accessibilityRole="header" style={[styles.section, textStyle(theme.typeTokens.titleSm), { color: theme.colors.text.primary }]}>
171:           {section.title}
172:         </Text>
173:       )}
174:       renderItem={({ item }) => {
175:         if ('chat' in item) return <ChatRow item={item.chat} onPress={openChat} />;
176:         const { message } = item;
177:         const title = chatsById.get(message.chatId)?.title ?? '';
178:         const date = new Date(message.createdAt).toLocaleDateString([], { dateStyle: 'medium' });
179:         return (
180:           <Pressable
181:             accessibilityRole="button"
182:             accessibilityLabel={`${title}, ${message.sender}, ${date}, ${message.preview}`}
183:             onPress={() => openChat(message.chatId, message.messageId)}
184:             style={({ pressed }) => [styles.message, pressed && { backgroundColor: theme.colors.bg.pressed }]}
185:           >
186:             <Text numberOfLines={1} style={[textStyle(theme.typeTokens.labelMd), { color: theme.colors.text.primary }]}>
187:               {title} · {message.sender} · {date}
188:             </Text>
189:             <Text numberOfLines={2} style={[textStyle(theme.typeTokens.bodyMd), { color: theme.colors.text.secondary }]}>
190:               {message.preview}
191:             </Text>
192:           </Pressable>
193:         );
194:       }}
195:       contentContainerStyle={sections.length === 0 ? styles.emptyList : undefined}
196:       ListEmptyComponent={loading || failed ? null : (
197:         <EmptyState iconName="action.search" title="No results" message="Try a different word or phrase." />
198:       )}
199:       ListFooterComponent={loading ? (
200:         <ActivityIndicator style={styles.loader} color={theme.colors.brand.primary} accessibilityLabel="Searching messages" />
201:       ) : failed ? (
202:         <View style={styles.footer}>
203:           <Text accessibilityRole="alert" style={[textStyle(theme.typeTokens.bodyMd), { color: theme.colors.error.text }]}>
204:             {"Couldn't search messages."}
205:           </Text>
206:           <Button variant="secondary" label="Retry" onPress={() => setRequest({ ...request })} />
207:         </View>
208:       ) : next ? (
209:         <View style={styles.footer}>
210:           <Button variant="secondary" label="Show more messages" onPress={() => setRequest({ cursor: next })} />
211:         </View>
212:       ) : null}
213:     />
214:   );
215: }
