226: });  1: /**
  2:  * Auth state for the app (M2-04, F1, D-78).
  3:  * - Restores the stored Supabase session on start and follows onAuthStateChange.
  4:  * - `mustChangePassword` comes from `app_metadata.must_change_password`, which only the
  5:  *   server can set (D-78); while it is true the root guard renders AND-02 alone.
  6:  * - The own `profiles` row is read through RLS after a normal sign-in. An RLS read before
  7:  *   the password change returns no row by design (D-78), so the profile is loaded again
  8:  *   when the flag clears.
  9:  */
 10: import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
 11: import type { Session } from '@supabase/supabase-js';
 12: import { supabase } from '../lib/supabase';
 13: import { saveSessionAccount } from './savedAccounts';
 14: 
 15: export type AuthStatus = 'loading' | 'signedOut' | 'mustChangePassword' | 'signedIn';
 16: 
 17: export interface AuthProfile {
 18:   avatar_url: string | null;
 19:   user_id: string;
 20:   username: string;
 21:   display_name: string;
 22: }
 23: 
 24: export type AuthProfileUpdate = Partial<Pick<AuthProfile, 'avatar_url' | 'username' | 'display_name'>>;
 25: 
 26: const PROFILE_AVATAR_BUCKET = 'avatars';
 27: 
 28: type ProfileRecord = AuthProfile;
 29: 
 30: async function withAvatarUrl(profile: ProfileRecord): Promise<AuthProfile> {
 31:   if (!profile.avatar_url || profile.avatar_url.startsWith('http')) return profile;
 32: 
 33:   const { data, error } = await supabase.storage
 34:     .from(PROFILE_AVATAR_BUCKET)
 35:     .createSignedUrl(profile.avatar_url, 60 * 60);
 36: 
 37:   return error || !data?.signedUrl ? { ...profile, avatar_url: null } : { ...profile, avatar_url: data.signedUrl };
 38: }
 39: 
 40: export interface AuthContextValue {
 41:   status: AuthStatus;
 42:   session: Session | null;
 43:   profile: AuthProfile | null;
 44:   refreshProfile: () => Promise<AuthProfile | null>;
 45:   updateProfile: (updates: AuthProfileUpdate) => Promise<AuthProfile>;
 46: }
 47: 
 48: const AuthContext = createContext<AuthContextValue | undefined>(undefined);
 49: 
 50: function requiresPasswordChange(session: Session | null): boolean {
 51:   const flag: unknown = session?.user.app_metadata?.['must_change_password'];
 52:   return flag === true;
 53: }
 54: 
 55: export function AuthProvider({ children }: { children: React.ReactNode }) {
 56:   const [status, setStatus] = useState<AuthStatus>('loading');
 57:   const [session, setSession] = useState<Session | null>(null);
 58:   const [profile, setProfile] = useState<AuthProfile | null>(null);
 59:   const profileUserIdRef = useRef<string | null>(null);
 60:   const sessionUserIdRef = useRef<string | null>(null);
 61: 
 62:   useEffect(() => {
 63:     if (!session) return;
 64:     void saveSessionAccount(session, profile).catch(() => {
 65:       // A temporary storage failure must not interrupt the active session.
 66:     });
 67:   }, [session, profile]);
 68: 
 69:   const refreshProfile = useCallback(async () => {
 70:     const userId = session?.user.id;
 71:     if (!userId) return null;
 72: 
 73:     profileUserIdRef.current = null;
 74:     const { data, error } = await supabase
 75:       .from('profiles')
 76:       .select('avatar_url, user_id, username, display_name')
 77:       .eq('user_id', userId)
 78:       .maybeSingle();
 79: 
 80:     if (error) throw error;
 81:     const resolvedProfile = data ? await withAvatarUrl(data) : null;
 82:     if (sessionUserIdRef.current !== userId) return null;
 83:     setProfile(resolvedProfile);
 84:     profileUserIdRef.current = userId;
 85:     return resolvedProfile;
 86:   }, [session?.user.id]);
 87: 
 88:   const updateProfile = useCallback(
 89:     async (updates: AuthProfileUpdate) => {
 90:       const userId = session?.user.id;
 91:       if (!userId) throw new Error('No signed-in user');
 92: 
 93:       const { data, error } = await supabase
 94:         .from('profiles')
 95:         .update(updates)
 96:         .eq('user_id', userId)
 97:         .select('avatar_url, user_id, username, display_name')
 98:         .single();
 99: 
100:       if (error) throw error;
101:       const resolvedProfile = await withAvatarUrl(data);
102:       if (sessionUserIdRef.current !== userId) return resolvedProfile;
103:       setProfile(resolvedProfile);
104:       profileUserIdRef.current = userId;
105:       return resolvedProfile;
106:     },
107:     [session?.user.id],
108:   );
109: 
110:   useEffect(() => {
111:     let active = true;
112:     let authRevision = 0;
113: 
114:     async function loadProfile(userId: string) {
115:       if (profileUserIdRef.current === userId) return;
116:       profileUserIdRef.current = userId;
117: 
118:       const { data, error } = await supabase
119:         .from('profiles')
120:         .select('avatar_url, user_id, username, display_name')
121:         .eq('user_id', userId)
122:         .maybeSingle();
123: 
124:       if (!active || sessionUserIdRef.current !== userId) return;
125: 
126:       if (error) {
127:         // Denied or offline: retry on the next auth event instead of looping.
128:         profileUserIdRef.current = null;
129:         return;
130:       }
131: 
132:       const resolvedProfile = data ? await withAvatarUrl(data) : null;
133:       if (!active || sessionUserIdRef.current !== userId) return;
134:       setProfile(resolvedProfile);
135:     }
136: 
137:     function applySession(next: Session | null, loadOwnProfile: boolean) {
138:       if (!active) return;
139: 
140:       const userChanged = sessionUserIdRef.current !== (next?.user.id ?? null);
141:       sessionUserIdRef.current = next?.user.id ?? null;
142:       if (userChanged) {
143:         profileUserIdRef.current = null;
144:         setProfile(null);
145:       }
146:       setSession(next);
147: 
148:       if (!next) {
149:         profileUserIdRef.current = null;
150:         setProfile(null);
151:         setStatus('signedOut');
152:         return;
153:       }
154: 
155:       if (requiresPasswordChange(next)) {
156:         profileUserIdRef.current = null;
157:         setProfile(null);
158:         setStatus('mustChangePassword');
159:         return;
160:       }
161: 
162:       setStatus('signedIn');
163:       if (loadOwnProfile || userChanged) {
164:         void loadProfile(next.user.id);
165:       }
166:     }
167: 
168:     supabase.auth
169:       .getSession()
170:       .then(({ data }) => {
171:         if (authRevision === 0) applySession(data.session, true);
172:       })
173:       .catch(() => {
174:         if (active && authRevision === 0) setStatus('signedOut');
175:       });
176: 
177:     const { data: listener } = supabase.auth.onAuthStateChange((event, next) => {
178:       // supabase-js holds its auth lock while this callback runs, so further client calls are deferred.
179:       const revision = ++authRevision;
180:       setTimeout(() => {
181:         if (revision === authRevision) applySession(next, event !== 'TOKEN_REFRESHED');
182:       }, 0);
183:     });
184: 
185:     return () => {
186:       active = false;
187:       listener.subscription.unsubscribe();
188:     };
189:   }, []);
190: 
191:   const value: AuthContextValue = { status, session, profile, refreshProfile, updateProfile };
192: 
193:   return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
194: }
195: 
196: /** Hook to consume the auth context. Must be used inside AuthProvider. */
197: export function useAuth(): AuthContextValue {
198:   const ctx = useContext(AuthContext);
199:   if (!ctx) throw new Error('useAuth must be used inside <AuthProvider>');
200:   return ctx;
201: }  1: /**
  2:  * The single chat-list query (M2-08, F2, D-44, D-94, proposed D-159).
  3:  *
  4:  * D-44 requires the unread counts to come from one query. The cache holds every synced row
  5:  * (6.4), so one statement returns every chat the caller is a member of with its own member row,
  6:  * its newest message, that message's sender name and media type, the unread count, the other
  7:  * members' highest read sequence and the other member of a direct chat. Archived chats are
  8:  * returned too, so the same read feeds the Archive view and the archive count in the header.
  9:  */
 10: import type { SQLiteDatabase } from 'expo-sqlite';
 11: import type {
 12:   ChatListSourceRow,
 13:   ChatMemberRow,
 14:   ChatRow,
 15:   MediaType,
 16:   MessageRow,
 17: } from '@dologram/shared';
 18: 
 19: const MEDIA_TYPES: readonly MediaType[] = ['photo', 'video', 'voice', 'file'];
 20: 
 21: type QueryRow = {
 22:   chat_payload: string;
 23:   member_payload: string;
 24:   last_message_payload: string | null;
 25:   last_sender_name: string | null;
 26:   last_media_payload: string | null;
 27:   unread_count: number;
 28:   other_max_read_seq: number;
 29:   other_member_id: string | null;
 30:   other_member_name: string | null;
 31: };
 32: 
 33: /**
 34:  * Unread = messages from other senders with a seq above the caller's last_read_seq, excluding
 35:  * deleted and expired messages (D-92); a deleted message keeps its seq and is filtered by
 36:  * `deleted_at`, and V2 expiry clears the content and sets deleted_at as well (D-111).
 37:  */
 38: const CHAT_LIST_SQL = `
 39: SELECT
 40:   c.payload AS chat_payload,
 41:   m.payload AS member_payload,
 42:   lm.payload AS last_message_payload,
 43:   COALESCE(
 44:     (SELECT n.nickname FROM cache_chat_members n WHERE n.chat_id = c.chat_id AND n.user_id = lm.sender_id AND n.nickname IS NOT NULL),
 45:     (SELECT p.display_name FROM cache_profiles p WHERE p.user_id = lm.sender_id)
 46:   ) AS last_sender_name,
 47:   (SELECT mm.payload FROM cache_message_media mm WHERE mm.message_id = lm.message_id LIMIT 1)
 48:     AS last_media_payload,
 49:   (SELECT COUNT(*) FROM cache_messages u
 50:      WHERE u.chat_id = c.chat_id
 51:        AND u.sender_id <> ?
 52:        AND u.seq IS NOT NULL
 53:        AND u.seq > m.last_read_seq
 54:        AND u.deleted_at IS NULL) AS unread_count,
 55:   (SELECT COALESCE(MAX(o.last_read_seq), 0) FROM cache_chat_members o
 56:      WHERE o.chat_id = c.chat_id AND o.user_id <> ?) AS other_max_read_seq,
 57:   (SELECT o.user_id FROM cache_chat_members o
 58:      WHERE o.chat_id = c.chat_id AND o.user_id <> ? LIMIT 1) AS other_member_id,
 59:   COALESCE(
 60:     (SELECT n.nickname FROM cache_chat_members n WHERE n.chat_id = c.chat_id AND n.user_id =
 61:       (SELECT o.user_id FROM cache_chat_members o WHERE o.chat_id = c.chat_id AND o.user_id <> ? LIMIT 1)
 62:       AND n.nickname IS NOT NULL),
 63:     (SELECT p.display_name FROM cache_profiles p WHERE p.user_id =
 64:       (SELECT o.user_id FROM cache_chat_members o WHERE o.chat_id = c.chat_id AND o.user_id <> ? LIMIT 1))
 65:   ) AS other_member_name
 66: FROM cache_chats c
 67: JOIN cache_chat_members m ON m.chat_id = c.chat_id AND m.user_id = ?
 68: LEFT JOIN cache_messages lm ON lm.message_id = (
 69:   SELECT y.message_id FROM cache_messages y
 70:    WHERE y.chat_id = c.chat_id
 71:    ORDER BY y.created_at DESC, y.seq DESC
 72:    LIMIT 1
 73: )
 74: `;
 75: 
 76: function parseJson(payload: string | null): unknown {
 77:   if (payload === null) return null;
 78:   try {
 79:     return JSON.parse(payload);
 80:   } catch {
 81:     return null;
 82:   }
 83: }
 84: 
 85: function parseMediaType(payload: string | null): MediaType | null {
 86:   const media = parseJson(payload);
 87:   if (typeof media !== 'object' || media === null) return null;
 88:   const value = (media as { media_type?: unknown }).media_type;
 89:   return MEDIA_TYPES.find((type) => type === value) ?? null;
 90: }
 91: 
 92: /** Reads every cached chat as one chat-list row; malformed payloads are skipped, never thrown. */
 93: export async function loadChatListRows(
 94:   db: SQLiteDatabase,
 95:   userId: string,
 96: ): Promise<ChatListSourceRow[]> {
 97:   const rows = await db.getAllAsync<QueryRow>(CHAT_LIST_SQL, [userId, userId, userId, userId, userId, userId]);
 98: 
 99:   const result: ChatListSourceRow[] = [];
100:   for (const row of rows) {
101:     const chat = parseJson(row.chat_payload) as ChatRow | null;
102:     const myMember = parseJson(row.member_payload) as ChatMemberRow | null;
103:     if (!chat || !myMember) continue;
104: 
105:     result.push({
106:       chat,
107:       myMember,
108:       lastMessage: parseJson(row.last_message_payload) as MessageRow | null,
109:       lastMediaType: parseMediaType(row.last_media_payload),
110:       lastSenderName: row.last_sender_name,
111:       unreadCount: row.unread_count,
112:       otherMaxReadSeq: row.other_max_read_seq,
113:       otherMemberId: row.other_member_id,
114:       otherMemberName: row.other_member_name,
115:     });
116:   }
117:   return result;
118: }  1: /**
  2:  * Chat list data for AND-03 and AND-04 (M2-08, F2, D-44, D-94).
  3:  *
  4:  * One read of the local cache feeds both screens and the archive count in the header. The list reloads when
  5:  * the sync engine merges rows (a Realtime event or a finished pass), when the screen regains focus
  6:  * and on pull to refresh, which runs a resync (6.4).
  7:  */
  8: import { useCallback, useMemo, useRef, useState } from 'react';
  9: import { useFocusEffect } from 'expo-router';
 10: import { buildChatList, type ChatListItem, type ChatListSourceRow } from '@dologram/shared';
 11: import { useAuth } from '../auth/AuthProvider';
 12: import { getLocalDatabase } from '../queue/db';
 13: import { subscribeCacheChange } from '../sync/cacheEvents';
 14: import { resyncNow } from '../sync/lifecycle';
 15: import { loadChatListRows } from './query';
 16: import { loadChatListPreferences, type ChatListPreferences } from './preferences';
 17: import { loadChatPreferences } from '../chats/preferences';
 18: 
 19: export type ChatListData = {
 20:   /** AND-03 rows in D-94 order; archived chats are left out. */
 21:   active: ChatListItem[];
 22:   /** AND-04 rows in D-94 order. */
 23:   archived: ChatListItem[];
 24:   ignored: ChatListItem[];
 25:   /** True until the first read of the cache resolves. */
 26:   loading: boolean;
 27:   /** A read failed; the last successful rows are still shown when there are any. */
 28:   error: boolean;
 29:   /** True while a pull-to-refresh resync runs. */
 30:   refreshing: boolean;
 31:   reload: () => Promise<void>;
 32:   refresh: () => Promise<void>;
 33: };
 34: 
 35: type LoadedRows = { userId: string; rows: ChatListSourceRow[]; preferences: ChatListPreferences };
 36: 
 37: // Keep the most recent local snapshot in memory so returning to the tab is instant. The cache is
 38: // keyed by account, so one user's chats can never be rendered for another account.
 39: const recentRowsByUser = new Map<string, LoadedRows>();
 40: // MainHeader and the currently visible list screen both consume this hook. Share the actual
 41: // cache read between them so navigation cannot briefly show two competing snapshots.
 42: const pendingLoadsByUser = new Map<string, Promise<LoadedRows>>();
 43: 
 44: async function loadSnapshotForUser(userId: string): Promise<LoadedRows> {
 45:   const pending = pendingLoadsByUser.get(userId);
 46:   if (pending) return pending;
 47: 
 48:   const request = (async () => {
 49:     const db = await getLocalDatabase();
 50:     const rows = await loadChatListRows(db, userId);
 51:     const nextPreferences = await loadChatListPreferences(userId);
 52:     const chatPreferences = await Promise.all(
 53:       rows.map((row) => loadChatPreferences(userId, row.chat.chat_id)),
 54:     );
 55:     const blockedIds = new Set(
 56:       rows
 57:         .filter((_, index) => chatPreferences[index]?.blocked)
 58:         .map((row) => row.chat.chat_id),
 59:     );
 60:     return {
 61:       userId,
 62:       rows: rows.filter((row) => !blockedIds.has(row.chat.chat_id)),
 63:       preferences: nextPreferences,
 64:     };
 65:   })();
 66: 
 67:   pendingLoadsByUser.set(userId, request);
 68:   try {
 69:     return await request;
 70:   } finally {
 71:     if (pendingLoadsByUser.get(userId) === request) pendingLoadsByUser.delete(userId);
 72:   }
 73: }
 74: 
 75: export function useChatList(folderChatIds?: readonly string[]): ChatListData {
 76:   const { session } = useAuth();
 77:   const userId = session?.user.id ?? null;
 78: 
 79:   const [loaded, setLoaded] = useState<LoadedRows | null>(() => (
 80:     userId && recentRowsByUser.has(userId)
 81:       ? recentRowsByUser.get(userId) ?? null
 82:       : null
 83:   ));
 84:   const [errorUserId, setErrorUserId] = useState<string | null>(null);
 85:   const error = userId !== null && errorUserId === userId;
 86:   const [refreshing, setRefreshing] = useState(false);
 87:   const inflight = useRef(new Set<string>());
 88:   const reloadRequested = useRef(new Set<string>());
 89:   const currentUserId = useRef(userId);
 90:   currentUserId.current = userId;
 91: 
 92:   const reload = useCallback(async () => {
 93:     if (!userId) return;
 94:     if (inflight.current.has(userId)) {
 95:       reloadRequested.current.add(userId);
 96:       return;
 97:     }
 98:     inflight.current.add(userId);
 99:     try {
100:       do {
101:         reloadRequested.current.delete(userId);
102:         const snapshot = await loadSnapshotForUser(userId);
103:         recentRowsByUser.set(userId, snapshot);
104:         if (currentUserId.current === userId) {
105:           setLoaded(snapshot);
106:           setErrorUserId(null);
107:         }
108:       } while (reloadRequested.current.has(userId));
109:     } catch {
110:       if (currentUserId.current === userId) setErrorUserId(userId);
111:     } finally {
112:       inflight.current.delete(userId);
113:     }
114:   }, [userId]);
115: 
116:   useFocusEffect(
117:     useCallback(() => {
118:       // Retained, hidden sections catch up on focus instead of rebuilding all three
119:       // lists for every cache event while another section is animating.
120:       const unsubscribe = subscribeCacheChange(() => void reload());
121:       void reload();
122:       return unsubscribe;
123:     }, [reload]),
124:   );
125: 
126:   const refresh = useCallback(async () => {
127:     setRefreshing(true);
128:     try {
129:       await resyncNow();
130:     } catch {
131:       // A failed resync keeps the cached list; the next foreground pass or pull retries.
132:     } finally {
133:       setRefreshing(false);
134:       await reload();
135:     }
136:   }, [reload]);
137: 
138:   // Rows of a previous account are never shown while the new account loads.
139:   const snapshot = userId !== null
140:     ? loaded?.userId === userId
141:       ? loaded
142:       : recentRowsByUser.get(userId) ?? null
143:     : null;
144:   const rows = snapshot?.rows ?? null;
145:   const preferences = snapshot?.preferences;
146: 
147:   // Both lists are built from one read and one reference time, so a row cannot show two labels.
148:   const lists = useMemo(() => {
149:     if (rows === null || userId === null || !preferences) {
150:       return { active: [] as ChatListItem[], archived: [] as ChatListItem[], ignored: [] as ChatListItem[] };
151:     }
152:     const now = new Date();
153:     const options = {
154:       userId,
155:       now,
156:       pinnedChatIds: preferences.pinned,
157:       ignoredChatIds: preferences.ignored,
158:       unreadChatIds: preferences.unread,
159:       deletedChatIds: preferences.deleted,
160:     };
161:     const active = buildChatList(rows, options);
162:     const visibleActive = folderChatIds
163:       ? active.filter((item) => folderChatIds.includes(item.chatId))
164:       : active;
165:     return {
166:       active: visibleActive,
167:       archived: buildChatList(rows, { ...options, archived: true }),
168:       ignored: buildChatList(rows, { ...options, ignored: true }),
169:     };
170:   }, [folderChatIds, preferences, rows, userId]);
171: 
172:   return {
173:     active: lists.active,
174:     archived: lists.archived,
175:     ignored: lists.ignored,
176:     loading: rows === null && !error,
177:     error,
178:     refreshing,
179:     reload,
180:     refresh,
181:   };
182: }  1: /**
  2:  * Open or create a direct chat (M2-07, AND-10, D-70, D-124, C-8).
  3:  *
  4:  * D-70 makes chats.direct_key unique, so a pair has at most one direct chat. The flow first checks
  5:  * the synced local cache for a chat with that member and opens it; otherwise it inserts the three
  6:  * rows of the contract in order (chats, the creator's owner row, the other member's row) and the
  7:  * server trigger sets direct_key.
  8:  *
  9:  * C-8/PF-31: a failure on the second member row can mean the pair already has a direct chat the
 10:  * cache did not know about. That case resyncs and opens the existing chat; a real failure is
 11:  * reported, never hidden.
 12:  */
 13: import type { SQLiteDatabase } from 'expo-sqlite';
 14: import {
 15:   createChat,
 16:   findDirectChatId,
 17:   insertMember,
 18:   isSavedMessagesChat,
 19:   listMyChats,
 20:   strings,
 21:   type DgClient,
 22: } from '@dologram/shared';
 23: import { loadChatListRows } from '../chatList/query';
 24: import { resyncNow } from '../sync/lifecycle';
 25: import { mutationErrorMessage } from './errors';
 26: 
 27: export type DirectChatOutcome =
 28:   | { kind: 'opened' | 'created'; chatId: string }
 29:   | { kind: 'failed'; message: string };
 30: 
 31: async function cachedDirectChatId(
 32:   db: SQLiteDatabase,
 33:   userId: string,
 34:   otherUserId: string,
 35: ): Promise<string | null> {
 36:   const rows = await loadChatListRows(db, userId);
 37:   return findDirectChatId(rows, { userId, otherUserId });
 38: }
 39: 
 40: export type OpenDirectChatArgs = {
 41:   client: DgClient;
 42:   db: SQLiteDatabase;
 43:   userId: string;
 44:   otherUserId: string;
 45:   /** A fresh client-generated chat id (D-10, D-100). */
 46:   newChatId: string;
 47: };
 48: 
 49: export async function openDirectChat({
 50:   client,
 51:   db,
 52:   userId,
 53:   otherUserId,
 54:   newChatId,
 55: }: OpenDirectChatArgs): Promise<DirectChatOutcome> {
 56:   // A cache read failure must not block the flow: the insert below still checks direct_key.
 57:   const existing = await cachedDirectChatId(db, userId, otherUserId).catch(() => null);
 58:   if (existing !== null) {
 59:     return { kind: 'opened', chatId: existing };
 60:   }
 61: 
 62:   // The local cache may lag behind a freshly signed-in device. For self-chat, check the server
 63:   // before creating a chat because the target should be the existing Saved Messages chat.
 64:   if (otherUserId === userId) {
 65:     const remoteChats = await listMyChats(client);
 66:     const remoteExisting = remoteChats.data?.find((chat) => isSavedMessagesChat(chat, userId))?.chat_id ?? null;
 67:     if (remoteExisting !== null) {
 68:       return { kind: 'opened', chatId: remoteExisting };
 69:     }
 70:   }
 71: 
 72:   const created = await createChat(client, {
 73:     chat_id: newChatId,
 74:     type: 'direct',
 75:     title: null,
 76:     created_by: userId,
 77:   });
 78:   if (created.error) {
 79:     return { kind: 'failed', message: mutationErrorMessage(created.error, strings.newChat.openFailed) };
 80:   }
 81: 
 82:   // D-124 branch 1: the creator's own first row.
 83:   const own = await insertMember(client, { chat_id: newChatId, user_id: userId, role: 'owner' });
 84:   if (own.error) {
 85:     return { kind: 'failed', message: mutationErrorMessage(own.error, strings.newChat.openFailed) };
 86:   }
 87: 
 88:   // Saved Messages is intentionally a one-member direct chat. The username search may target the
 89:   // caller, so do not insert the same member a second time.
 90:   if (otherUserId === userId) {
 91:     await resyncNow();
 92:     return { kind: 'created', chatId: newChatId };
 93:   }
 94: 
 95:   // D-124 branch 2: the other member, with no shared-chat rule for a direct chat (D-70).
 96:   const other = await insertMember(client, {
 97:     chat_id: newChatId,
 98:     user_id: otherUserId,
 99:     role: 'member',
100:   });
101:   if (other.error) {
102:     await resyncNow();
103:     const existingAfter = await cachedDirectChatId(db, userId, otherUserId).catch(() => null);
104:     if (existingAfter !== null) {
105:       return { kind: 'opened', chatId: existingAfter };
106:     }
107:     return {
108:       kind: 'failed',
109:       message: mutationErrorMessage(other.error, strings.newChat.openFailed),
110:     };
111:   }
112: 
113:   await resyncNow();
114:   return { kind: 'created', chatId: newChatId };
115: } 1: /**
 2:  * Cache reads for AND-12 (M2-07, D-44, D-91).
 3:  *
 4:  * Chat info renders from the synced local cache, so opening it does not depend on the network. The
 5:  * rows are stored as the server JSON (6.4); a malformed payload is skipped rather than thrown.
 6:  */
 7: import type { SQLiteDatabase } from 'expo-sqlite';
 8: import type { ChatMemberRow, ChatRow, ProfileRow } from '@dologram/shared';
 9: 
10: export type ChatInfoSource = {
11:   chat: ChatRow | null;
12:   members: ChatMemberRow[];
13:   profiles: ProfileRow[];
14: };
15: 
16: function parsePayload<T>(payload: string | null): T | null {
17:   if (payload === null) return null;
18:   try {
19:     const parsed: unknown = JSON.parse(payload);
20:     return typeof parsed === 'object' && parsed !== null ? (parsed as T) : null;
21:   } catch {
22:     return null;
23:   }
24: }
25: 
26: export async function loadChatInfoSource(
27:   db: SQLiteDatabase,
28:   chatId: string,
29: ): Promise<ChatInfoSource> {
30:   const chatRow = await db.getFirstAsync<{ payload: string }>(
31:     'SELECT payload FROM cache_chats WHERE chat_id = ?',
32:     [chatId],
33:   );
34:   const chat = parsePayload<ChatRow>(chatRow?.payload ?? null);
35: 
36:   const memberRows = await db.getAllAsync<{ payload: string }>(
37:     'SELECT payload FROM cache_chat_members WHERE chat_id = ?',
38:     [chatId],
39:   );
40:   const members: ChatMemberRow[] = [];
41:   for (const row of memberRows) {
42:     const member = parsePayload<ChatMemberRow>(row.payload);
43:     if (member) members.push(member);
44:   }
45: 
46:   const profiles: ProfileRow[] = [];
47:   if (members.length > 0) {
48:     const placeholders = members.map(() => '?').join(', ');
49:     const profileRows = await db.getAllAsync<{ payload: string }>(
50:       `SELECT payload FROM cache_profiles WHERE user_id IN (${placeholders})`,
51:       members.map((member) => member.user_id),
52:     );
53:     for (const row of profileRows) {
54:       const profile = parsePayload<ProfileRow>(row.payload);
55:       if (profile) profiles.push(profile);
56:     }
57:   }
58: 
59:   return { chat, members, profiles };
60: }
61: 
62: export type CachedContactRow = { user_id: string; display_name: string | null };
63: 
64: /**
65:  * Every other member of every cached chat: the people the caller already shares a chat with, which
66:  * is exactly who D-70 lets the caller put into a group.
67:  */
68: export async function loadCachedContacts(db: SQLiteDatabase, userId: string): Promise<CachedContactRow[]> {
69:   return db.getAllAsync<CachedContactRow>(
70:     `SELECT DISTINCT m.user_id AS user_id, p.display_name AS display_name
71:        FROM cache_chat_members m
72:        LEFT JOIN cache_profiles p ON p.user_id = m.user_id
73:       WHERE m.user_id <> ?`,
74:     [userId],
75:   );
76: } 1: /**
 2:  * The "people you already share a chat with" list (AND-11, AND-12, D-70).
 3:  *
 4:  * Read from the cache, so the checklist renders offline; `exclude` leaves out the caller and the
 5:  * members a chat already has.
 6:  */
 7: import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
 8: import { useFocusEffect } from 'expo-router';
 9: import { buildContactList, type ContactCandidate } from '@dologram/shared';
10: import { useAuth } from '../auth/AuthProvider';
11: import { getLocalDatabase } from '../queue/db';
12: import { subscribeCacheChange } from '../sync/cacheEvents';
13: import { loadCachedContacts } from './infoQuery';
14: 
15: export type ContactsData = {
16:   loading: boolean;
17:   error: boolean;
18:   contacts: ContactCandidate[];
19:   reload: () => Promise<void>;
20: };
21: 
22: export function useContacts(exclude: readonly string[] = []): ContactsData {
23:   const { session } = useAuth();
24:   const userId = session?.user.id ?? null;
25: 
26:   const [loaded, setLoaded] = useState<{ userId: string; contacts: ContactCandidate[] } | null>(
27:     null,
28:   );
29:   const [error, setError] = useState(false);
30:   const inflight = useRef(false);
31:   const excludeKey = [...exclude].sort().join(',');
32: 
33:   const reload = useCallback(async () => {
34:     if (!userId) return;
35:     if (inflight.current) return;
36:     inflight.current = true;
37:     try {
38:       const db = await getLocalDatabase();
39:       const rows = await loadCachedContacts(db, userId);
40:       const excluded = excludeKey === '' ? [] : excludeKey.split(',');
41:       setLoaded({ userId, contacts: buildContactList(rows, userId, excluded) });
42:       setError(false);
43:     } catch {
44:       setError(true);
45:     } finally {
46:       inflight.current = false;
47:     }
48:   }, [userId, excludeKey]);
49: 
50:   useEffect(() => subscribeCacheChange(() => void reload()), [reload]);
51: 
52:   useFocusEffect(
