  2:  * CMP-05: Avatar component.
  3:  * Sizes: 24, 28, 40, 48, 56, 64, 96.
  4:  * Initials: first code point of each of the first two words.
  5:  * Fill: sum of UTF-16 code units of id modulo 7, into avatarFills.
  6:  * Special: Saved Messages uses bookmark icon; deleted/former use person icon.
  7:  * 12.3, D-95
  8:  */
  9: import React, { useState } from 'react';
 10: import { Image, Text, View } from 'react-native';
 11: import { useTheme } from '../theme/ThemeProvider';
 12: import { textStyle } from '../theme/typography';
 13: import { Icon } from './Icon';
 14: 
 15: export type AvatarSize = 24 | 28 | 40 | 48 | 56 | 64 | 96;
 16: 
 17: export interface AvatarProps {
 18:   id: string;
 19:   displayName: string;
 20:   size?: AvatarSize;
 21:   /** Public profile image URL. Falls back to initials when absent or unavailable. */
 22:   imageUrl?: string | null;
 23:   /** When true, renders the Saved Messages bookmark icon. */
 24:   isSavedMessages?: boolean;
 25:   /** When 'deleted' or 'former', renders the person icon on muted bg. */
 26:   personState?: 'normal' | 'deleted' | 'former';
 27: }
 28: 
 29: /** Computes initials from a display name (first code point of first two words). */
 30: function getInitials(name: string): string {
 31:   const words = name.trim().split(/\s+/).filter(Boolean);
 32:   const first = words[0] ? Array.from(words[0])[0] ?? '' : '';
 33:   const second = words[1] ? Array.from(words[1])[0] ?? '' : '';
 34:   return (first + second).toUpperCase();
 35: }
 36: 
 37: /** Fill index: sum of UTF-16 code units of id modulo 7. */
 38: function getFillIndex(id: string): number {
 39:   let sum = 0;
 40:   for (let i = 0; i < id.length; i++) {
 41:     sum += id.charCodeAt(i);
 42:   }
 43:   return sum % 7;
 44: }
 45: 
 46: /** Font size relative to avatar size. */
 47: function initialsSize(size: AvatarSize): number {
 48:   if (size <= 28) return 10;
 49:   if (size <= 40) return 14;
 50:   if (size <= 48) return 16;
 51:   if (size <= 64) return 20;
 52:   return 28;
 53: }
 54: 
 55: export function Avatar({
 56:   id,
 57:   displayName,
 58:   size = 40,
 59:   imageUrl,
 60:   isSavedMessages = false,
 61:   personState = 'normal',
 62: }: AvatarProps) {
 63:   const theme = useTheme();
 64:   const c = theme.colors;
 65:   const fills = theme.avatarFills;
 66:   const [failedImageUrl, setFailedImageUrl] = useState<string | null>(null);
 67: 
 68:   let bgColor: string;
 69:   let content: React.ReactNode;
 70: 
 71:   if (isSavedMessages) {
 72:     bgColor = c.brand.primary;
 73:     content = (
 74:       <Icon
 75:         name="chat.saved"
 76:         size="sm"
 77:         color={c.text.inverse}
 78:         accessibilityLabel="Saved Messages"
 79:       />
 80:     );
 81:   } else if (personState === 'deleted' || personState === 'former') {
 82:     bgColor = c.badge.muted.bg;
 83:     content = (
 84:       <Icon
 85:         name="person.deleted"
 86:         size="sm"
 87:         color={c.badge.muted.text}
 88:         accessibilityLabel={personState === 'deleted' ? 'Deleted account' : 'Former member'}
 89:       />
 90:     );
 91:   } else if (imageUrl && failedImageUrl !== imageUrl) {
 92:     bgColor = c.badge.muted.bg;
 93:     content = (
 94:       <Image
 95:         source={{ uri: imageUrl }}
 96:         style={{ width: size, height: size }}
 97:         resizeMode="cover"
 98:         onError={() => setFailedImageUrl(imageUrl)}
 99:         accessibilityLabel="Profile picture"
100:       />
101:     );
102:   } else {
103:     const fillIdx = getFillIndex(id);
104:     bgColor = fills[fillIdx] ?? fills[0];
105:     const initials = getInitials(displayName) || '?';
106:     const fontSize = initialsSize(size);
107: 
108:     content = (
109:       <Text
110:         style={[
111:           textStyle(theme.typeTokens.labelLg),
112:           {
113:             fontSize,
114:             lineHeight: fontSize * 1.2,
115:             color: c.text.inverse,
116:             fontWeight: '600',
117:           },
118:         ]}
119:         numberOfLines={1}
120:         maxFontSizeMultiplier={1}
121:         accessible={false}
122:       >
123:         {initials}
124:       </Text>
125:     );
126:   }
127: 
128:   return (
129:     <View
130:       style={{
131:         width: size,
132:         height: size,
133:         borderRadius: size / 2,
134:         backgroundColor: bgColor,
135:         alignItems: 'center',
136:         justifyContent: 'center',
137:         overflow: 'hidden',
138:       }}
139:       accessibilityElementsHidden
140:       importantForAccessibility="no"
141:     >
142:       {content}
143:     </View>
144:   );
145: }  1: /**
  2:  * CMP-01: Button and IconButton components.
