 21: export type ButtonVariant = 'primary' | 'secondary' | 'text' | 'danger' | 'pill';
 22: 
 23: export interface ButtonProps extends Omit<PressableProps, 'style' | 'children'> {
 24:   label: string;
 25:   variant?: ButtonVariant;
 26:   loading?: boolean;
 27:   fullWidth?: boolean;
 28: }
 29: 
 30: export function Button({
 31:   label,
 32:   variant = 'primary',
 33:   loading = false,
 34:   fullWidth = false,
 35:   disabled,
 36:   accessibilityLabel,
 37:   ...rest
 38: }: ButtonProps) {
 39:   const theme = useTheme();
 40:   const c = theme.colors;
 41:   const isDisabled = disabled || loading;
 42:   const showSpinner = useDelayedFlag(loading);
 43: 
 44:   const containerStyle: ViewStyle = {
 45:     height: 48,
 46:     minWidth: 88,
 47:     borderRadius: theme.radius.md,
 48:     paddingHorizontal: theme.space[6],
 49:     alignItems: 'center',
 50:     justifyContent: 'center',
 51:     flexDirection: 'row',
 52:     gap: theme.space[2],
 53:     ...(fullWidth ? { width: '100%' } : {}),
 54:     ...(variant === 'primary' && { backgroundColor: c.brand.primary }),
 55:     ...(variant === 'secondary' && {
 56:       backgroundColor: 'transparent',
 57:       borderWidth: 1.5,
 58:       borderColor: c.brand.primary,
 59:     }),
 60:     ...(variant === 'danger' && { backgroundColor: c.error.bg }),
 61:     ...(variant === 'pill' && {
 62:       backgroundColor: c.brand.primary,
 63:       height: 44,
 64:       minWidth: 100,
 65:       minHeight: 44,
 66:       borderRadius: 24,
 67:       paddingHorizontal: 18,
 68:     }),
 69:     ...(variant === 'text' && { backgroundColor: 'transparent' }),
 70:     ...(isDisabled && { opacity: 0.5 }),
 71:   };
 72: 
 73:   const labelColor: string =
 74:     variant === 'primary'
 75:       ? c.text.inverse
 76:       : variant === 'pill'
 77:         ? c.bubble.outgoingText
 78:       : variant === 'danger'
 79:         ? c.error.text
 80:         : c.brand.primary;
 81: 
 82:   const labelStyle: TextStyle = {
 83:     ...textStyle(theme.typeTokens.labelLg),
 84:     color: labelColor,
 85:   };
 86: 
 87:   return (
 88:     <Pressable
 89:       style={({ pressed }) => [
 90:         containerStyle,
 91:         pressed && !isDisabled
 92:           ? {
 93:               backgroundColor:
 94:                 variant === 'primary' || variant === 'pill'
 95:                   ? c.brand.pressed
 96:                   : c.bg.pressed,
 97:             }
 98:           : undefined,
 99:       ]}
100:       disabled={isDisabled}
101:       accessibilityLabel={accessibilityLabel ?? label}
102:       accessibilityRole="button"
103:       accessibilityState={{ busy: loading, disabled: isDisabled }}
104:       {...rest}
105:     >
106:       {showSpinner ? (
107:         <ActivityIndicator
108:           size="small"
109:           color={labelColor}
110:           accessibilityLabel="Loading"
111:         />
112:       ) : (
113:         <Text style={labelStyle} maxFontSizeMultiplier={1.5} numberOfLines={1}>
114:           {label}
115:         </Text>
116:       )}
117:     </Pressable>
118:   );
119: }
