130: 
131: export function IconButton({
132:   iconName,
133:   iconSize = 'md',
134:   color,
135:   accessibilityLabel,
136:   disabled,
137:   ...rest
138: }: IconButtonProps) {
139:   const theme = useTheme();
140:   const iconColor = color ?? theme.colors.text.primary;
141: 
142:   return (
143:     <Pressable
144:       style={({ pressed }) => ({
145:         width: 48,
146:         height: 48,
147:         alignItems: 'center',
148:         justifyContent: 'center',
149:         borderRadius: 24, // visual circle is 40, tap target is 48
150:         backgroundColor: pressed ? theme.colors.bg.pressed : 'transparent',
151:         opacity: disabled ? 0.5 : 1,
152:       })}
153:       disabled={disabled}
154:       accessibilityLabel={accessibilityLabel}
155:       accessibilityRole="button"
156:       {...rest}
157:     >
158:       <Icon
159:         name={iconName}
160:         size={iconSize}
161:         color={iconColor}
162:       />
163:     </Pressable>
164:   );
165: }  1: /**
