 26: const ChatRow = React.memo(function ChatRow({ item, onPress, onLongPress, compactPreview = false }: ChatRowProps) {
 27:   const theme = useTheme();
 28:   const c = theme.colors;
 29:   const unread = item.unreadCount > 0;
 30: 
 31:   const nameStyle = textStyle(
 32:     unread ? { ...theme.typeTokens.titleSm, weight: 700 } : theme.typeTokens.titleSm,
 33:   );
 34:   const previewStyle = textStyle(
 35:     unread ? { ...theme.typeTokens.bodyMd, weight: 600 } : theme.typeTokens.bodyMd,
 36:   );
 37:   const previewColor = unread ? c.text.primary : c.text.secondary;
 38: 
 39:   return (
 40:     <Pressable
 41:       style={({ pressed }) => [
 42:         styles.row,
 43:         { backgroundColor: pressed ? c.bg.pressed : c.bg.app },
 44:       ]}
 45:       onPress={() => onPress(item.chatId)}
 46:       onLongPress={onLongPress ? () => onLongPress(item) : undefined}
 47:       accessibilityRole="button"
 48:       accessibilityLabel={item.accessibilityLabel}
 49:       accessibilityHint={onLongPress ? 'Long press for chat actions' : undefined}
 50:     >
 51:       <Avatar
 52:         id={item.avatarId}
 53:         displayName={item.avatarName}
 54:         size={56}
 55:         isSavedMessages={item.savedMessages}
 56:       />
