 58:       <View style={styles.body}>
 59:         <View style={styles.nameLine}>
 60:           <View style={styles.nameContent}>
 61:             <Text style={[nameStyle, styles.title, { color: c.text.primary }]} numberOfLines={1}>
 62:               {item.title}
 63:             </Text>
 64:             {item.muted ? (
 65:               <Icon name="action.mute" size="sm" color={c.text.secondary} />
 66:             ) : null}
 67:           </View>
 68:           {item.pinned ? <Icon name="action.star" size="sm" color={c.text.secondary} /> : null}
 69:         </View>
 70: 
 71:         <View style={styles.previewLine}>
 72:           <View style={styles.previewContent}>
 73:             {item.ownStatus !== null ? (
 74:               <Icon
 75:                 name={item.ownStatus === 'seen' ? 'status.seen' : 'status.sent'}
