 77:                 color={c.text.secondary}
 78:               />
 79:             ) : null}
 80:             <Text
 81:               style={[previewStyle, styles.preview, compactPreview && styles.compactPreview, { color: previewColor }]}
 82:               numberOfLines={1}
 83:             >
 84:               {item.preview}
 85:             </Text>
 86:             {item.timeLabel.length > 0 ? (
 87:               <Text style={[previewStyle, { color: previewColor }]} numberOfLines={1}>
