 90:             ) : null}
 91:           </View>
 92:           {unread ? <Badge count={item.unreadCount} muted={item.muted} /> : null}
 93:         </View>
 94:       </View>
 95:     </Pressable>
 96:   );
 97: }, (previous, next) => (
 98:   previous.onPress === next.onPress
 99:   && previous.onLongPress === next.onLongPress
100:   && previous.compactPreview === next.compactPreview
101:   // Cache reads rebuild plain row objects, even when nothing visible changed.
102:   // Keep unchanged avatars, text and icons out of navigation-time commits.
103:   && (previous.item === next.item || (
