149: /**
150:  * The initial chat-list placeholder uses one native-driven animation for every row. Keeping the
151:  * animation at the list level avoids starting one timer and one loop per skeleton block, which
152:  * makes the first render lighter and keeps the transition stable on slower devices.
153:  */
154: export function ChatListSkeleton({ rows = 8 }: { rows?: number }) {
155:   const theme = useTheme();
156:   const c = theme.colors;
157:   const opacity = useRef(new Animated.Value(0.58)).current;
158: 
159:   useEffect(() => {
160:     if (theme.reduceMotion) {
161:       opacity.setValue(0.75);
162:       return;
163:     }
164: 
165:     const animation = Animated.loop(
166:       Animated.sequence([
167:         Animated.timing(opacity, {
168:           toValue: 0.92,
169:           duration: theme.motion.duration.spinner,
170:           useNativeDriver: true,
171:           isInteraction: false,
172:         }),
173:         Animated.timing(opacity, {
174:           toValue: 0.58,
175:           duration: theme.motion.duration.spinner,
176:           useNativeDriver: true,
177:           isInteraction: false,
178:         }),
179:       ]),
180:     );
181:     animation.start();
182:     return () => animation.stop();
183:   }, [opacity, theme.motion.duration.spinner, theme.reduceMotion]);
184: 
185:   return (
186:     <Animated.View accessible accessibilityLabel="Loading" style={{ opacity }}>
187:       {Array.from({ length: rows }, (_, index) => (
188:         <View key={index} style={styles.row}>
189:           <View
190:             style={[styles.skeletonCircle, { backgroundColor: c.skeleton.base }]}
191:             accessibilityElementsHidden
192:             importantForAccessibility="no"
193:           />
194:           <View style={[styles.body, styles.skeletonBody]} accessibilityElementsHidden>
195:             <View style={[styles.skeletonName, { backgroundColor: c.skeleton.base }]} />
196:             <View style={[styles.skeletonPreview, { backgroundColor: c.skeleton.base }]} />
197:           </View>
198:         </View>
199:       ))}
200:     </Animated.View>
201:   );
202: }
