 18: export interface SearchFieldProps extends Omit<TextInputProps, 'onChangeText'> {
 19:   /** Called ~150 ms after the user stops typing. */
 20:   onSearch: (query: string) => void;
 21:   /** Immediate notification for controlled fields; onSearch may remain debounced. */
 22:   onChangeText?: (query: string) => void;
 23:   debounceMs?: number;
 24:   inputRef?: React.Ref<TextInput>;
 25: }
 26: 
 27: export function SearchField({
 28:   onSearch,
 29:   onChangeText,
 30:   debounceMs = 150,
 31:   placeholder = strings.search.placeholder,
 32:   inputRef,
 33:   value: controlledValue,
 34:   defaultValue = '',
 35:   onSubmitEditing,
 36:   style,
 37:   ...inputProps
 38: }: SearchFieldProps) {
 39:   const theme = useTheme();
 40:   const c = theme.colors;
 41:   const [internalValue, setInternalValue] = useState(defaultValue);
 42:   const value = controlledValue ?? internalValue;
 43:   const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 44:   const pendingValue = useRef<string | null>(null);
 45:   const currentValue = useRef(value);
 46:   currentValue.current = value;
 47:   const onSearchRef = useRef(onSearch);
 48:   onSearchRef.current = onSearch;
 49: 
 50:   useEffect(() => {
 51:     return () => {
 52:       if (timerRef.current) clearTimeout(timerRef.current);
 53:     };
 54:   }, [debounceMs]);
 55: 
 56:   useEffect(() => {
 57:     if (controlledValue !== undefined && pendingValue.current !== controlledValue && timerRef.current) {
 58:       clearTimeout(timerRef.current);
 59:       timerRef.current = null;
 60:     }
 61:   }, [controlledValue]);
 62: 
 63:   const handleChange = (text: string) => {
 64:     if (controlledValue === undefined) setInternalValue(text);
 65:     currentValue.current = text;
 66:     pendingValue.current = text;
 67:     onChangeText?.(text);
 68:     if (timerRef.current) clearTimeout(timerRef.current);
 69:     if (!text || debounceMs <= 0) onSearch(text);
 70:     else timerRef.current = setTimeout(() => { timerRef.current = null; onSearchRef.current(text); }, debounceMs);
 71:   };
 72: 
 73:   const handleClear = () => {
 74:     handleChange('');
 75:   };
 76: 
 77:   return (
 78:     <View
 79:       style={[
 80:         styles.container,
 81:         {
 82:           height: 44,
 83:           borderRadius: theme.radius.full,
 84:           paddingLeft: theme.space[3],
 85:         },
 86:       ]}
 87:     >
 88:       <View pointerEvents="none" style={[StyleSheet.absoluteFill, {
 89:         top: 2, bottom: 2, borderRadius: theme.radius.full, backgroundColor: c.bg.surface,
 90:       }]} />
 91:       <Icon name="action.search" size="sm" color={c.text.muted} />
 92: 
 93:       <TextInput
 94:         {...inputProps}
 95:         ref={inputRef}
 96:         style={[
 97:           styles.input,
 98:           { ...textStyle(theme.typeTokens.bodyMd), color: c.text.primary }, style,
 99:         ]}
100:         value={value}
101:         onChangeText={handleChange}
102:         placeholder={placeholder}
103:         placeholderTextColor={c.text.muted}
104:         returnKeyType="search"
105:         clearButtonMode="never"
106:         accessibilityRole="search"
107:         accessibilityLabel={inputProps.accessibilityLabel ?? placeholder}
108:         onSubmitEditing={(event) => {
109:           if (timerRef.current) clearTimeout(timerRef.current);
110:           timerRef.current = null;
111:           onSearch(currentValue.current);
112:           onSubmitEditing?.(event);
113:         }}
114:       />
115: 
116:       {value.length > 0 ? (
117:         <Pressable
118:           onPress={handleClear}
119:           accessibilityLabel={strings.search.clear}
120:           accessibilityRole="button"
121:           style={styles.clearButton}
122:         >
123:           <Icon name="nav.close" size="sm" color={c.text.muted} />
124:         </Pressable>
125:       ) : null}
126:     </View>
127:   );
128: }
