 7: /** UTF-16 display ranges, including composition, compatibility and lowercase expansions. */
 8: export function highlightRanges(text: string, query: string): HighlightRange[] {
 9:   const needle = normalizeSearch(query);
10:   if (!needle) return [];
11:   if (/^[\x00-\x7F]*$/.test(text)) {
12:     const lower = text.toLowerCase();
13:     const ranges: HighlightRange[] = [];
14:     for (let from = 0; from < lower.length;) {
15:       const found = lower.indexOf(needle, from);
16:       if (found < 0) break;
17:       const previous = ranges[ranges.length - 1];
18:       if (previous && found <= previous.end) previous.end = Math.max(previous.end, found + needle.length);
19:       else ranges.push({ start: found, end: found + needle.length });
20:       from = found + 1;
21:     }
22:     return ranges;
23:   }
24:   // Normalize prefixes to retain provenance when a later combining character composes or
25:   // reorders earlier code points. Lowercase the complete string for contextual Greek sigma.
26:   let prefix = '';
27:   let normalized = '';
28:   let offsets: HighlightRange[] = [];
29:   let sourceOffset = 0;
30:   for (const point of text) {
31:     prefix += point;
32:     const next = prefix.normalize('NFKC');
33:     let common = 0;
34:     while (common < normalized.length && common < next.length && normalized[common] === next[common]) common++;
35:     const start = offsets[common]?.start ?? sourceOffset;
36:     offsets = offsets.slice(0, common);
37:     for (let index = common; index < next.length; index++) offsets.push({ start, end: sourceOffset + point.length });
38:     sourceOffset += point.length;
39:     normalized = next;
40:   }
41:   const lower = normalized.toLowerCase();
42:   const lowerOffsets: HighlightRange[] = [];
43:   let index = 0;
44:   for (const point of normalized) {
45:     const span = { start: offsets[index].start, end: offsets[index + point.length - 1].end };
46:     for (let count = 0; count < point.toLowerCase().length; count++) lowerOffsets.push(span);
47:     index += point.length;
48:   }
49:   const ranges: HighlightRange[] = [];
50:   let from = 0;
51:   for (;;) {
52:     const found = lower.indexOf(needle, from);
53:     if (found < 0) break;
54:     const span = { start: lowerOffsets[found].start, end: lowerOffsets[found + needle.length - 1].end };
55:     const previous = ranges[ranges.length - 1];
56:     if (previous && span.start <= previous.end) previous.end = Math.max(previous.end, span.end);
57:     else ranges.push(span);
58:     from = found + 1;
59:   }
60:   return ranges;
61: }
