63: export function searchPreview(content: string, query: string): string {
64:   const match = highlightRanges(content, query)[0];
65:   let start = Math.max(0, (match?.start ?? 0) - 36);
66:   let end = Math.min(content.length, Math.max(start + 160, match?.end ?? 0));
67:   // Never cut a surrogate pair or detach a combining mark from its base.
68:   while (start > 0 && /[\p{M}\uDC00-\uDFFF]/u.test(content[start])) start--;
69:   while (end < content.length && /[\p{M}\uDC00-\uDFFF]/u.test(content[end])) end++;
70:   return `${start > 0 ? '…' : ''}${content.slice(start, end)}${end < content.length ? '…' : ''}`;
