20: /** Exact, prefix, substring; ties use activity, normalized title, then stable entity ID. */
21: export function rankSearchNames<T extends NamedResult>(items: readonly T[], query: string): T[] {
22:   const normalized = normalizeSearch(query);
23:   const score = (item: T) => Math.min(...[item.title, ...(item.aliases ?? [])].map((name) => rank(name, normalized)));
24:   const compare = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
25:   return items.filter((item) => !normalized || score(item) < 3).sort((a, b) =>
26:     score(a) - score(b) || b.sortMs - a.sortMs || compare(normalizeSearch(a.title), normalizeSearch(b.title)) || compare(a.id, b.id));
