30: export async function loadSearchPeople(
31:   db: SQLiteDatabase, userId: string, allowedChatIds: readonly string[], query: string,
32:   signal: AbortSignal, deadline = Date.now() + SEARCH_DEADLINE_MS,
33: ): Promise<SearchPerson[]> {
