38:   const blockedPeople = new Set(rows.filter((row, index) => row.chat.type === 'direct' && preferences[index].blocked)
39:     .map((row) => row.otherMemberId).filter((id): id is string => id !== null));
40:   const unblocked = rows.filter((row, index) => row.myMember.user_id === userId && !preferences[index].blocked);
41:   const allowed = new Set(allowedChatIds);
42:   const eligible = unblocked.filter((row) => allowed.has(row.chat.chat_id) && !organization.deleted.includes(row.chat.chat_id));
43:   const contacts = await readSearch(() => db.getAllAsync<{ user_id: string; display_name: string | null }>(
44:     `SELECT DISTINCT member.user_id, profile.display_name
45:        FROM cache_chat_members member
46:        JOIN cache_chat_members own ON own.chat_id = member.chat_id AND own.user_id = ?
47:        LEFT JOIN cache_profiles profile ON profile.user_id = member.user_id
48:        WHERE member.chat_id IN (SELECT value FROM json_each(?)) AND member.user_id <> ?`,
49:     [userId, JSON.stringify(eligible.map((row) => row.chat.chat_id)), userId],
50:   ), signal, deadline);
