54:     // Deleted direct chats can be explicitly reopened, but cannot supply searchable content.
55:     const chatId = findDirectChatId(unblocked, { userId, otherUserId: contact.user_id });
56:     const direct = unblocked.find((row) => row.chat.chat_id === chatId);
