 43: function scopeIds(scope: SearchScope): string[] {
 44:   if (!scope.userId || scope.allowedChatIds.some((id) => typeof id !== 'string' || !id)) throw new SearchFailure('invalid');
 45:   if (scope.chatId !== undefined && !scope.allowedChatIds.includes(scope.chatId)) throw new SearchFailure('unavailable');
