 49: /** Only one bounded source batch is retained, irrespective of history size. */
 50: async function* scanMatches(
 51:   db: SQLiteDatabase, scope: SearchScope, query: string, cursor: SearchCursor | null,
 52:   signal: AbortSignal, deadline: number,
 53: ): AsyncGenerator<MessageMatch> {
 54:   const ids = scopeIds(scope);
 55:   if (!query || ids.length === 0) return;
 56:   let after = cursor;
 57:   while (!signal.aborted) {
 58:     const rows = await readSearch(() => db.getAllAsync<CachedMessage>(
 59:       `SELECT m.message_id, m.chat_id, m.created_at,
 60:           json_extract(m.payload, '$.content') AS content,
 61:           CASE WHEN m.sender_id = own.user_id THEN ?
 62:             ELSE COALESCE(NULLIF(sender.nickname, ''), profile.display_name, ?) END AS sender,
 63:           (SELECT group_concat(DISTINCT json_extract(media.payload, '$.media_type'))
 64:              FROM cache_message_media media
 65:              WHERE media.message_id = m.message_id AND json_extract(media.payload, '$.deleted_at') IS NULL
 66:           ) AS media_types
 67:         FROM cache_messages m
 68:         JOIN cache_chat_members own ON own.chat_id = m.chat_id AND own.user_id = ?
 69:         LEFT JOIN cache_chat_members sender ON sender.chat_id = m.chat_id AND sender.user_id = m.sender_id
 70:         LEFT JOIN cache_profiles profile ON profile.user_id = m.sender_id
 71:         WHERE m.chat_id IN (SELECT value FROM json_each(?))
 72:           AND m.deleted_at IS NULL AND m.seq IS NOT NULL
 73:           ${after ? 'AND (m.created_at, m.message_id) < (?, ?)' : ''}
 74:         ORDER BY m.created_at DESC, m.message_id DESC LIMIT ?`,
 75:       [strings.search.you, strings.chatList.unknownMember, scope.userId, JSON.stringify(ids),
 76:         ...(after ? [after.createdAt, after.messageId] : []), BATCH_SIZE],
 77:     ), signal, deadline);
 78:     for (const row of rows) {
 79:       if (signal.aborted) throw new SearchFailure('cancelled');
 80:       if (Date.now() >= deadline) throw new SearchFailure('timeout');
 81:       const match = messageMatch(row, query);
 82:       if (match) yield match;
 83:     }
 84:     if (rows.length < BATCH_SIZE) return;
 85:     const last = rows[rows.length - 1];
 86:     after = { createdAt: last.created_at, messageId: last.message_id };
 87:   }
 88: }
