 90: /** Backward-compatible delivered page API used by the existing global screen. */
 91: export async function searchCachedMessages(
 92:   db: SQLiteDatabase, userId: string, chatIds: string, query: string,
 93:   cursor: SearchCursor | null, signal: AbortSignal,
