100: export async function searchMessagePage(
101:   db: SQLiteDatabase, scope: SearchScope, query: string, cursor: SearchCursor | null,
102:   signal: AbortSignal, deadline = Date.now() + SEARCH_DEADLINE_MS,
103: ): Promise<MessagePage> {
104:   const matches: MessageMatch[] = [];
105:   if (signal.aborted) return { matches, next: null };
106:   for await (const match of scanMatches(db, scope, normalizeSearch(query), cursor, signal, deadline)) {
107:     if (matches.length === PAGE_SIZE) return { matches, next: matches[PAGE_SIZE - 1] };
108:     matches.push(match);
109:   }
110:   if (signal.aborted) throw new SearchFailure('cancelled');
111:   return { matches, next: null };
112: }
