114: export async function countMessageMatches(
115:   db: SQLiteDatabase, scope: SearchScope, query: string, signal: AbortSignal,
116:   deadline = Date.now() + SEARCH_DEADLINE_MS,
117: ): Promise<ConversationSummary[]> {
118:   const summaries = new Map<string, ConversationSummary>();
119:   for await (const match of scanMatches(db, scope, normalizeSearch(query), null, signal, deadline)) {
120:     const previous = summaries.get(match.chatId);
121:     if (previous) previous.deliveredMatchCount++;
122:     else summaries.set(match.chatId, { chatId: match.chatId, deliveredMatchCount: 1, latestMatch: match });
123:   }
124:   if (signal.aborted) throw new SearchFailure('cancelled');
125:   return [...summaries.values()]; // insertion order follows the latest matching timestamp and ID
126: }
