130: /** Pending rows stay separate from delivered pagination/counts and retain their queue ID. */
131: export async function searchScopedMessages(
132:   db: SQLiteDatabase, scope: SearchScope & { chatId: string }, query: string,
133:   cursor: SearchCursor | null, signal: AbortSignal, getUnsent: () => Promise<QueueItem[]>,
