156:     seen.add(item.temp_id);
157:     const match = messageMatch({ message_id: item.temp_id, chat_id: scope.chatId,
158:       created_at: new Date(item.created_at).toISOString(), content: item.payload.content,
159:       sender: strings.search.you, media_types: item.payload.attachments.map((attachment) => attachment.media_type).join(',') }, normalized);
