 3: export class SearchFailure extends Error {
 4:   constructor(public readonly kind: 'timeout' | 'cancelled' | 'unavailable' | 'invalid') {
 5:     super(kind === 'timeout' ? strings.search.timeout : strings.search.unavailable);
