12: /** Logical cancellation: late native settlements are observed but cannot publish results. */
13: export function readSearch<T>(read: () => Promise<T>, signal: AbortSignal, deadline: number): Promise<T> {
14:   if (signal.aborted) return Promise.reject(new SearchFailure('cancelled'));
15:   const remaining = deadline - Date.now();
16:   if (remaining <= 0) return Promise.reject(new SearchFailure('timeout'));
17:   return new Promise<T>((resolve, reject) => {
18:     const cleanup = () => { clearTimeout(timer); signal.removeEventListener('abort', cancel); };
19:     const cancel = () => { cleanup(); reject(new SearchFailure('cancelled')); };
20:     const timer = setTimeout(() => { cleanup(); reject(new SearchFailure('timeout')); }, remaining);
21:     signal.addEventListener('abort', cancel, { once: true });
22:     Promise.resolve().then(() => {
23:       if (signal.aborted) throw new SearchFailure('cancelled');
24:       return read();
25:     }).then((value) => {
26:       cleanup();
27:       if (signal.aborted) reject(new SearchFailure('cancelled'));
28:       else if (Date.now() >= deadline) reject(new SearchFailure('timeout'));
29:       else resolve(value);
30:     }, (error: unknown) => { cleanup(); reject(error); });
31:   });
