 34: export interface ThemeContextValue {
 35:   /** Resolved colors for the current scheme. */
 36:   colors: ThemeColors;
 37:   /** Named type tokens, e.g. theme.typeTokens.bodyLg */
 38:   typeTokens: typeof typeTokens;
 39:   avatarFills: typeof avatarFills;
 40:   space: typeof space;
 41:   radius: typeof radius;
 42:   /** Elevation level → { android, shadowOpacityLight, shadowOpacityDark } */
 43:   elevation: typeof elevation;
 44:   motion: typeof motion;
 45:   z: typeof z;
 46:   /** Resolved color scheme ("light" | "dark"). */
 47:   scheme: ColorScheme;
 48:   /** User-chosen setting ("system" | "light" | "dark"). */
 49:   setting: ThemeSetting;
 50:   setSetting: (setting: ThemeSetting) => void;
 51:   /** True when the platform "Remove animations" preference is on. */
 52:   reduceMotion: boolean;
 53:   /** Helper: get a duration value, collapsed to instant when reduceMotion */
 54:   duration: (key: keyof typeof motion.duration, allowFade?: boolean) => number;
 55: }
