 61: export function ThemeProvider({ children }: { children: React.ReactNode }) {
 62:   const systemScheme = useColorScheme();
 63:   const [setting, setSetting] = useState<ThemeSetting>('system');
 64:   const [reduceMotion, setReduceMotion] = useState(false);
 65: 
 66:   // Load persisted setting
 67:   useEffect(() => {
 68:     AsyncStorage.getItem(STORAGE_KEY).then((val) => {
 69:       if (val === 'light' || val === 'dark' || val === 'system') {
 70:         setSetting(val);
 71:       }
 72:     }).catch(() => {
 73:       // Fallback to "system" already set
 74:     });
 75:   }, []);
 76: 
 77:   // Persist setting changes
 78:   useEffect(() => {
 79:     AsyncStorage.setItem(STORAGE_KEY, setting).catch(() => {
 80:       // AsyncStorage failure: silent, setting is still in state
 81:     });
 82:   }, [setting]);
 83: 
 84:   // Reduce motion
 85:   useEffect(() => {
 86:     let cancelled = false;
 87:     AccessibilityInfo.isReduceMotionEnabled().then((val) => {
 88:       if (!cancelled) setReduceMotion(val);
 89:     }).catch(() => {});
 90:     const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion);
 91:     return () => {
 92:       cancelled = true;
 93:       sub.remove();
 94:     };
 95:   }, []);
 96: 
 97:   const scheme: ColorScheme =
 98:     setting === 'system'
 99:       ? systemScheme === 'dark'
100:         ? 'dark'
101:         : 'light'
102:       : setting;
103: 
104:   const colors: ThemeColors = color[scheme];
105: 
106:   function updateSetting(s: ThemeSetting) {
107:     setSetting(s);
108:   }
109: 
110:   // Duration helper: collapses to instant (or fast for opacity fades) under reduceMotion
111:   function duration(key: keyof typeof motion.duration, allowFade = false): number {
112:     if (!reduceMotion) return motion.duration[key];
113:     return allowFade ? motion.duration.reduceMotion : motion.duration.instant;
114:   }
115: 
116:   const value: ThemeContextValue = {
117:     colors,
118:     typeTokens,
119:     avatarFills,
120:     space,
121:     radius,
122:     elevation,
123:     motion,
124:     z,
125:     scheme,
126:     setting,
127:     setSetting: updateSetting,
128:     reduceMotion,
129:     duration,
130:   };
131: 
132:   return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
133: }
