135: /** Hook to consume the theme context. Must be used inside ThemeProvider. */
136: export function useTheme(): ThemeContextValue {
137:   const ctx = useContext(ThemeContext);
138:   if (!ctx) throw new Error('useTheme must be used inside <ThemeProvider>');
139:   return ctx;
140: }
